import sys

def solve():
    s = sys.stdin.readline().strip()

    # Check for presence of @
    if '@' not in s:
        print("NO")
        return

    parts = s.split('@')
    if len(parts) != 2:
        print("NO")
        return

    username, rest = parts

    # Validate username
    if not (1 <= len(username) <= 16):
        print("NO")
        return
    if not all(c.isalnum() or c == '_' for c in username):
        print("NO")
        return

    # Split rest into hostname and resource
    if '/' in rest:
        host_resource = rest.split('/')
        if len(host_resource) != 2:
            print("NO")
            return
        hostname, resource = host_resource
    else:
        hostname = rest
        resource = ""

    # Validate hostname
    if not (1 <= len(hostname) <= 32):
        print("NO")
        return

    words = hostname.split('.')
    if not words or any(w == '' for w in words):
        print("NO")
        return

    for word in words:
        if not (1 <= len(word) <= 16):
            print("NO")
            return
        if not all(c.isalnum() or c == '_' for c in word):
            print("NO")
            return

    # Validate resource (optional)
    if resource:
        if not (1 <= len(resource) <= 16):
            print("NO")
            return

        if not all(c.isalnum() or c == '_' for c in resource):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
